<section className="section" id="properties" style={{display:homepage.properties_intro?.visible===false?'none':undefined,...cmsBackground(homepage,'properties_intro')}}><p className="eyebrow dark">{cmsValue(homepage,'properties_intro','eyebrow','THE LISTINGS / 001—008')}</p><div className="sectionhead"><h2>{cmsValue(homepage,'properties_intro','title','PROPERTY. NO GUESSWORK.')}</h2><p>{cmsValue(homepage,'properties_intro','description','From a family home to an investment property, explore spaces and request an in-person inspection when you are ready.')}</p></div><div className="searchbar" style={{display:homepage.properties_filters?.visible===false?'none':undefined,...cmsBackground(homepage,'properties_filters')}}><label className="searchfield"><span>⌕</span><input value={query} onChange={e=>SQ(e.target.value)} placeholder={cmsValue(homepage,'properties_filters','description','Search by property or location — e.g. Lekki, Abuja')}/></label><label className="typefield"><span>{cmsValue(homepage,'properties_filters','eyebrow','PROPERTY TYPE')}</span><select value={type} onChange={e=>ST(e.target.value)}>{typeOptions.map(t=><option key={t}>{t}</option>)}</select></label><a href={cmsValue(homepage,'properties_filters','buttonUrl','#inspection')} className="searchbutton">{cmsValue(homepage,'properties_filters','buttonText','Book a visit')}</a></div><div className="resultsline"><b>{filtered.length.toString().padStart(2,'0')} PROPERTIES</b><span>FEATURED COLLECTION · NIGERIA</span></div><div className="demo-notice" style={{display:homepage.properties_notice?.visible===false?'none':undefined,...cmsBackground(homepage,'properties_notice')}}><span className="demo-mark">G</span><span><b>{listingLoadFailed?'LISTINGS TEMPORARILY UNAVAILABLE':liveListings?'LIVE LISTINGS':cmsValue(homepage,'properties_notice','eyebrow','LISTINGS BEING UPDATED')}</b><small>{listingLoadFailed?'We could not retrieve current property inventory. Please refresh shortly or contact G-BEST for assistance.':liveListings?'Published properties managed by the G-BEST admin dashboard.':cmsValue(homepage,'properties_notice','title','Our current property collection is being refreshed. Please contact G-BEST for available listings.')+' '+cmsValue(homepage,'properties_notice','description','Only published properties managed by the G-BEST team will appear here.') }</small></span><span className="demo-pill">{listingLoadFailed?'OFFLINE':liveListings?'DATABASE':cmsValue(homepage,'properties_notice','buttonText','UPDATING')}</span></div><div className="quick-filters" aria-label="Quick property filters">{TYPES.map(t=><button key={t} type="button" className={type===t?'active':''} onClick={()=>ST(t)}>{t}</button>)}<button type="button" className={savedOnly?'active':''} aria-pressed={savedOnly} onClick={()=>SetSavedOnly(v=>!v)}>♡ SAVED ({saved.length})</button><button type="button" className="clear-filter" onClick={()=>{ST('All properties');SQ('');SetSavedOnly(false)}}>Reset filters ↺</button></div><div className="grid grid-six">{visibleProperties.map((x,i)=><article key={x.id} className="property-card" onClick={e=>{if(!e.target.closest('button,a,input,select,textarea'))SD(x)}} onKeyDown={e=>{if(e.target===e.currentTarget&&(e.key==='Enter'||e.key===' ')){e.preventDefault();SD(x)}}} tabIndex={0} role="button" aria-label={'Open full details for '+x.name}><div className="photo-wrap"><span className={'property-availability '+(x.status==='sold'?'is-sold':'is-available')}>{x.status==='sold'?'SOLD':'AVAILABLE'}</span><img src={propertyImages(x)[galleryIndexes[x.id]||0]||x.img} alt={x.name+" image "+((galleryIndexes[x.id]||0)+1)} loading={i<3?"eager":"lazy"} decoding="async" onError={e=>{e.currentTarget.onerror=null;e.currentTarget.style.display="none";e.currentTarget.closest(".photo-wrap")?.classList.add("photo-unavailable")}}/>{propertyImages(x).length>1&&<div className="property-image-navigation"><button type="button" aria-label={"Previous image for "+x.name} onClick={()=>SetGalleryIndexes(v=>({...v,[x.id]:((v[x.id]||0)+propertyImages(x).length-1)%propertyImages(x).length}))}>‹</button><span>{(galleryIndexes[x.id]||0)+1} / {propertyImages(x).length}</span><button type="button" aria-label={"Next image for "+x.name} onClick={()=>SetGalleryIndexes(v=>({...v,[x.id]:((v[x.id]||0)+1)%propertyImages(x).length}))}>›</button></div>}{x.video_url&&<button type="button" className="property-video-play" aria-label={"Play property video for "+x.name} onClick={()=>SD(x)}>▶</button>}<span className="property-tag">{x.type}</span><button type="button" className="save-property" aria-label={(saved.includes(String(x.id))?'Remove saved property ':'Save property ')+x.name} aria-pressed={saved.includes(String(x.id))} onClick={()=>toggleSaved(x)}>{saved.includes(String(x.id))?'♥ SAVED':'♡ SAVE'}</button></div><div className="pad"><small className="loc">⌖ {x.loc}</small><h3>{x.name}</h3><p>{x.desc}</p><div className="facts"><span>⌂ {x.size}</span><span>{x.type==='Land'?'LAND PLOT':x.beds+' BED'}</span><span>{x.type==='Land'?'TITLE TO VERIFY':x.baths+' BATH'}</span></div><div className="property-card-reference"><span>PROPERTY ID</span><strong>{displayPropertyCode(x.propertyCode||propertyCode(x.id))}</strong><button type="button" className="copy-property-id" onClick={()=>copyPropertyCode(x.propertyCode||propertyCode(x.id))} aria-label={"Copy property ID "+(x.propertyCode||propertyCode(x.id))}>{copiedCode===(x.propertyCode||propertyCode(x.id))?"COPIED":"COPY"}</button></div><div className="price"><b>{x.price}</b><button type="button" className="view-property-button" onClick={()=>SD(x)}>VIEW PROPERTY</button></div><button type="button" className="property-booking-cta" disabled={String(x.status||'').toLowerCase()==='sold'} onClick={()=>choose(x)}>{String(x.status||'').toLowerCase()==='sold'?'PROPERTY SOLD':'BOOK INSPECTION'} <span aria-hidden="true">↗</span></button></div></article>)}</div>{filtered.length>visibleCount&&<div className="load-more-wrap"><p>Showing {visibleProperties.length} of {filtered.length} properties</p><button type="button" className="load-more" onClick={()=>SetVisibleCount(n=>Math.min(n+6,filtered.length))}>{cmsValue(homepage,'properties_filters','extraText','LOAD MORE PROPERTIES')} <span>({filtered.length-visibleProperties.length} remaining)</span></button></div>}{filtered.length>0&&visibleCount>=filtered.length&&filtered.length>6&&<p className="all-loaded">YOU'RE ALL CAUGHT UP · {filtered.length} PROPERTIES</p>}{filtered.length===0&&<p className="empty-state">{listingLoadFailed?'Published listings are temporarily unavailable. Please refresh shortly or contact G-BEST for assistance.':liveListings?'There are currently no published properties. Please check back soon or contact G-BEST for assistance.':'No matching properties in this collection. Try another location or property type.'}</p>}<p className="note">{listingLoadFailed?'Live listings could not be loaded. No sample inventory is being shown as a substitute.':liveListings?'Confirm current availability, ownership, title documents, pricing and property details directly with G-BEST before making a transaction.':'Listings shown are illustrative design examples, not verified active listings. Confirm availability, title, pricing and property details with G-BEST before making a transaction.'}</p></section>
