<section className="why" id="why" style={{display:homepage.why_intro?.visible===false?'none':undefined,...cmsBackground(homepage,'why_intro')}}><div className="why-left"><p className="eyebrow">{cmsValue(homepage,'why_intro','eyebrow','MADE FOR THE NIGERIAN PROPERTY JOURNEY')}</p><h2>{cmsValue(homepage,'why_intro','title','ASK BETTER. CHECK TWICE. Move smart.')}</h2><p>{cmsValue(homepage,'why_intro','description','Property decisions deserve more than polished pictures. Start with a location, ask the right questions and arrange a physical inspection before committing.')}</p><a className="goldbtn" href={cmsValue(homepage,'why_intro','buttonUrl','#inspection')}>{cmsValue(homepage,'why_intro','buttonText','Plan your inspection')} </a></div><div className="why-widgets"><article style={{display:homepage.why_discover?.visible===false?'none':undefined,...cmsBackground(homepage,'why_discover')}}><span>{cmsValue(homepage,'why_discover','eyebrow','01 / DISCOVER')}</span><b>{cmsValue(homepage,'why_discover','title','Browse with purpose.')}</b><p>{cmsValue(homepage,'why_discover','description','Search properties by location and type, with essential details up front.')}</p></article><article style={{display:homepage.why_inspect?.visible===false?'none':undefined,...cmsBackground(homepage,'why_inspect')}}><span>{cmsValue(homepage,'why_inspect','eyebrow','02 / INSPECT')}</span><b>{cmsValue(homepage,'why_inspect','title','See it for yourself.')}</b><p>{cmsValue(homepage,'why_inspect','description','Request a physical viewing at a preferred date and time.')}</p></article><article style={{display:homepage.why_decide?.visible===false?'none':undefined,...cmsBackground(homepage,'why_decide')}}><span>{cmsValue(homepage,'why_decide','eyebrow','03 / DECIDE')}</span><b>{cmsValue(homepage,'why_decide','title','Move with clarity.')}</b><p>{cmsValue(homepage,'why_decide','description','Your appointment remains pending until the G-BEST team approves it.')}</p></article><div className="nigeria-note" style={{display:homepage.why_note?.visible===false?'none':undefined,...cmsBackground(homepage,'why_note')}}><b>{cmsValue(homepage,'why_note','eyebrow','G-BEST / NIGERIA')}</b><span>{cmsValue(homepage,'why_note','title','Local perspective. Personal service.')} {cmsValue(homepage,'why_note','description','Property with purpose.')}</span></div></div></section>
